<?php use VazinCMS\Security; ?><section class="title"><div><h1>سفارش <?=Security::e($order['order_number'])?></h1><p><?=Security::e($order['customer'].' — '.$order['email'])?></p></div><a class="button secondary" href="/admin/orders">بازگشت</a></section><section class="grid order-summary"><article class="panel"><span>محصول</span><b><?=Security::e($order['product_name'])?></b></article><article class="panel"><span>مبلغ نهایی</span><b><?=Security::e((string)$order['amount'].' '.$order['currency'])?></b></article><?php if((float)$order['discount_amount']>0):?><article class="panel"><span>تخفیف</span><b><?=Security::e($order['discount_amount'].' '.$order['currency'].' — '.$order['discount_code'])?></b></article><?php endif;?><article class="panel"><span>وضعیت</span><b><?=Security::e($order['status'])?></b></article></section><section class="split"><div class="panel"><h2>تغییر وضعیت</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>وضعیت<select name="status"><?php foreach(['pending'=>'در انتظار','paid'=>'پرداخت‌شده','processing'=>'در حال انجام','completed'=>'تکمیل‌شده','cancelled'=>'لغوشده','refunded'=>'بازپرداخت'] as $v=>$l):?><option value="<?=$v?>" <?=$order['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><button>ذخیره وضعیت</button></form><p class="hint">با تکمیل سفارش، سرویس مشتری به‌صورت خودکار ساخته می‌شود.</p></div><div class="panel"><h2>جزئیات</h2><dl><dt>زمان ثبت</dt><dd><?=Security::e((string)$order['created_at'])?></dd><dt>یادداشت</dt><dd><?=nl2br(Security::e((string)$order['notes']))?></dd><?php if($service):?><dt>سرویس</dt><dd>#<?=$service['id']?> — <?=Security::e($service['status'])?></dd><?php endif;?></dl></div></section>
